head.script:
scwin.exeFun = function(v) {
    return v + "  의 합";
}
scwin.trigger1_onclick = function(e) {
    dataList2.removeAll();
};
scwin.__isData = function() {
    var el = WebSquare.wUnit.getJq("#gridView2_body_tbody tr");
    for (var i = 0; i < el.length; i++) {
        if (WebSquare.wUnit.getJq(el[i]).css("display") == "none") {
            return true;
        }
        return false;
    }
}
scwin.checkVal = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'gridView2_scrollY_div')).getPropertyValue('overflow-y') == 'hidden';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 removeAll버튼을 클릭한다.
    //Run the sample file and click the removeAll button.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 모든 데이터가 사라지고 세로스크롤도 생기지 않는다.(이전에는 불필요한 새로스크롤이 생겼음)
    //All data disappears and vertical scrolling does not occur (previously unnecessary new scrolling occurred).
    WebSquare.wUnit.addCommand("assert", "scwin.__isData()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
